//! 📐️ Editable rectangular native guides map to four real IDML ruler guides with owned grouping labels.
use super::*;
fn labels(page:&str,index:usize,edge:&str)->XmlNode{element("Properties",Vec::new(),vec![element("Label",Vec::new(),vec![element("KeyValuePair",vec![("Key","semio:guide-page".into()),("Value",page.into())],Vec::new()),element("KeyValuePair",vec![("Key","semio:guide-index".into()),("Value",index.to_string())],Vec::new()),element("KeyValuePair",vec![("Key","semio:guide-edge".into()),("Value",edge.into())],Vec::new())])])}
fn label<'a>(node:&'a XmlNode,key:&str)->Result<Option<&'a str>,String>{Ok(nodes(node,"KeyValuePair")?.into_iter().find(|node|attr(node,"Key")==Some(key)).and_then(|node|attr(node,"Value")))}
pub(crate) fn nodes_for(page:&Page,index:usize,x:f64,position:usize)->Result<Vec<XmlNode>,String>{let guide=page.guides.get(index).ok_or("layout.idml.guide-index")?;if [guide.x,guide.y,guide.width,guide.height].iter().any(|value|!value.is_finite()){return Err("layout.idml.guide-geometry".into());}Ok([("left","Vertical",guide.x+x),("top","Horizontal",guide.y),("right","Vertical",guide.x+guide.width+x),("bottom","Horizontal",guide.y+guide.height)].into_iter().map(|(edge,orientation,location)|element("Guide",vec![("Self",format!("{}-guide-{index}-{edge}",page.id)),("Orientation",orientation.into()),("Location",location.to_string()),("FitToPage","true".into()),("PageIndex",position.to_string())],vec![labels(&page.id,index,edge)])).collect())}
pub(super) fn import(spread:&XmlNode,pages:&mut[Page],origins:&[(f64,f64,f64,f64)])->Result<(),String>{let mut groups:BTreeMap<(usize,usize),[Option<f64>;4]>=BTreeMap::new();
    for guide in children(spread).iter().filter(|node|local(node)=="Guide"){let location=attr(guide,"Location").unwrap_or("0").parse::<f64>().map_err(|_|"layout.idml.guide-geometry")?;if !location.is_finite(){return Err("layout.idml.guide-geometry".into());}
        if let Some(id)=label(guide,"semio:guide-page")?{let page=pages.iter().position(|page|page.id==id).ok_or("layout.idml.guide-page")?;let index=label(guide,"semio:guide-index")?.ok_or("layout.idml.guide-index")?.parse::<usize>().map_err(|_|"layout.idml.guide-index")?;if index>=MAX_INTERCHANGE_ITEMS{return Err("layout.idml.guide-index".into());}let edge=match label(guide,"semio:guide-edge")?{Some("left")=>0,Some("top")=>1,Some("right")=>2,Some("bottom")=>3,_=>return Err("layout.idml.guide-edge".into())};let row=groups.entry((page,index)).or_insert([None;4]);if row[edge].replace(location-if edge==0||edge==2{origins[page].0}else{origins[page].1}).is_some(){return Err("layout.idml.duplicate-guide-edge".into());}}
        else{let position=attr(guide,"PageIndex").unwrap_or("0").parse::<usize>().map_err(|_|"layout.idml.guide-page")?;let page=pages.get_mut(position).ok_or("layout.idml.guide-page")?;let(x,y,_,_)=origins[position];page.guides.push(match attr(guide,"Orientation").unwrap_or("Horizontal"){"Horizontal"=>LayoutRect{x:0.0,y:location-y,width:page.width,height:0.0},"Vertical"=>LayoutRect{x:location-x,y:0.0,width:0.0,height:page.height},_=>return Err("layout.idml.guide-orientation".into())});}
    }
    for((page,_),edges)in groups{let[left,top,right,bottom]=edges;let(left,top,right,bottom)=(left.ok_or("layout.idml.guide-edges")?,top.ok_or("layout.idml.guide-edges")?,right.ok_or("layout.idml.guide-edges")?,bottom.ok_or("layout.idml.guide-edges")?);pages[page].guides.push(LayoutRect{x:left,y:top,width:right-left,height:bottom-top});}Ok(())
}
